#!/bin/bash
# CIFAR-10, ResNet-50: calibration pass, all arms, 2 epochs on a 5k subset.
# Generated by benchmarks/slurm/generate_jobs.py — edit that file, not this one.
# See docs/reports/plan_exp_step1.md §6 and benchmarks/slurm/README.md.
# Submit from the repository root:  sbatch benchmarks/slurm/cifar10/calibrate_resnet50_cifar.sh

#SBATCH --account=def-msh-ab
#SBATCH --job-name=cal_resnet50_cifar
#SBATCH --gpus=h100_1g.10gb:1
#SBATCH --cpus-per-task=8
#SBATCH --mem=16G
#SBATCH --time=00:15:00
#SBATCH --output=benchmarks/slurm/logs/%x-%j.out

# --time: 2 epochs x 7 arms on a 5000-example subset; dominated by env setup and the first-step hook/eigendecomposition warm-up, not by training. Generous on purpose.
# Dataset: cifar10, read from $DATA_ROOT (default $SLURM_SUBMIT_DIR/dataset; an ImageNet job
# overrides it with the node-local copy it stages below). Compute nodes have no internet, and
# --no-allow-download turns a missing dataset into a clear error rather than a network timeout.

set -euo pipefail
cd "$SLURM_SUBMIT_DIR"

module purge
module load StdEnv/2023 gcc/13.3 cuda/12.6 python/3.11.5

virtualenv --no-download "$SLURM_TMPDIR/env"
source "$SLURM_TMPDIR/env/bin/activate"
pip install --no-index --upgrade pip
pip install --no-index -r requirements-cluster.txt

export PYTHONPATH="$SLURM_SUBMIT_DIR/src:$SLURM_SUBMIT_DIR"
DATA_ROOT="${DATA_ROOT:-$SLURM_SUBMIT_DIR/dataset}"

# Calibration: 2 short epochs of every arm on a 5000-example training subset, printing per-arm
# steps/s, median step time and peak CUDA memory. Its job is to turn this model's --time value
# from an extrapolation into a measurement, and to confirm every arm fits the 10 GB MIG slice.
# Run this BEFORE the training jobs.
python -m benchmarks.resnet50_cifar.bench \
  --arms diag kfac ekfac tkfac tekfac adam adamw \
  --epochs 2 \
  --budget-mode epochs \
  --train-subset 5000 \
  --num-workers 8 \
  --no-allow-download \
  --data-root "$DATA_ROOT" \
  --output-dir "$SLURM_SUBMIT_DIR/benchmarks/outputs/cifar10/resnet50_cifar/_calibration"
